// ---------- scoring ----------
function zOf(h){let s=0,w=0;(h.fokwaarden||[]).forEach(f=>{const v=num(f.waarde),g=num(f.gemiddelde),sd=num(f.sd);if(v!=null&&g!=null&&sd&&sd>0){const b=num(f.betrouwbaarheid);const r=b!=null?Math.max(.1,b/100):.5;s+=r*(v-g)/sd;w+=r}});return w?s/w:null}
function perfOf(h){const parts=[];const cm=num(h.hoogste_niveau_cm);if(cm!=null)parts.push(clamp((cm-110)/50*100));const o=h.nakomelingen||{};const sp=num(o.sport);if(sp&&sp>0){parts.push(clamp(((num(o.m140)||0)/sp)*150+((num(o.m150)||0)/sp)*150))}return parts.length?parts.reduce((a,b)=>a+b,0)/parts.length:null}
function healthOf(h){const w={"N/N":100,"N/WFFS":60,"WFFS/WFFS":0}[h.wffs];const o={vrij:100,bevinding:25}[h.ocd];return((w==null?50:w)+(o==null?50:o))/2}
function ancCount(h){return PED_KEYS.filter(k=>h.stamboom&&h.stamboom[k]).length}
function completeOf(h){const c=[!!h.ueln,!!(h.stamboom&&h.stamboom.v),!!(h.stamboom&&h.stamboom.m),ancCount(h)>=10,zOf(h)!=null,num(h.hoogste_niveau_cm)!=null,!!h.wffs&&h.wffs!=="onbekend",!!h.ocd&&h.ocd!=="onbekend",(h.bronnen||[]).some(b=>b&&b.naam)];return c.filter(Boolean).length/c.length*100}

function foalPedigree(s,m,maxLen){const ped={};
  function add(prefix,h,depth){if(!h||prefix.length>maxLen)return;ped[prefix]=h.naam;
    const sb=h.stamboom||{};Object.keys(sb).forEach(k=>{if(!sb[k]||!/^[vm]+$/.test(k))return;const p=prefix+k;if(p.length<=maxLen&&!ped[p])ped[p]=sb[k]});}
  add("v",s);add("m",m);
  // verdiep met stambomen van voorouders die zelf in de database staan
  for(let pass=0;pass<4;pass++){Object.keys(ped).forEach(p=>{const h=byName(ped[p]);if(!h||!h.stamboom)return;Object.keys(h.stamboom).forEach(k=>{if(!h.stamboom[k]||!/^[vm]+$/.test(k))return;const q=p+k;if(q.length<=maxLen&&!ped[q])ped[q]=h.stamboom[k]})})}
  return ped}
function coi(s,m){const L=5;const ped=foalPedigree(s,m,L);const ent=Object.keys(ped).map(p=>[p,norm(ped[p])]).filter(e=>e[1]);
  const sire=ent.filter(e=>e[0][0]==="v"),dam=ent.filter(e=>e[0][0]==="m");
  const idAt=(p)=>norm(ped[p]);let F=0;const common={};
  sire.forEach(([a,ida])=>dam.forEach(([b,idb])=>{if(ida!==idb)return;
    for(let i=1;i<a.length;i++){const pa=a.slice(0,i);const x=idAt(pa);if(!x)continue;for(let j=1;j<b.length;j++){if(idAt(b.slice(0,j))===x)return}}
    const c=Math.pow(.5,a.length+b.length-1);F+=c;(common[ida]=common[ida]||{naam:ped[a],bijdrage:0,paden:[]});common[ida].bijdrage+=c;common[ida].paden.push(a.toUpperCase()+" x "+b.toUpperCase())}));
  let known=0,total=0;for(let g=1;g<=L;g++){total+=Math.pow(2,g)}known=Object.keys(ped).length;
  return{F,common:Object.values(common).sort((x,y)=>y.bijdrage-x.bijdrage),known,total,gens:L}}

function match(s,m){const w=state.w,t=state.t;const warnings=[],reasons=[],weak=[];let excluded=false;
  const zs=zOf(s),zm=zOf(m);const zArr=[zs,zm].filter(x=>x!=null);const z=zArr.length?zArr.reduce((a,b)=>a+b,0)/zArr.length:null;
  const gen=z==null?null:clamp(50+z*25);
  const ps=perfOf(s),pm=perfOf(m);const pArr=[ps,pm].filter(x=>x!=null);const perf=pArr.length?pArr.reduce((a,b)=>a+b,0)/pArr.length:null;
  const c=coi(s,m);const coiScore=clamp(100-c.F*800);
  const health=(healthOf(s)+healthOf(m))/2;const data=(completeOf(s)+completeOf(m))/2;
  const comps={gen,perf,coi:coiScore,health,data};
  let sum=0,ws=0;Object.keys(comps).forEach(k=>{if(comps[k]!=null&&w[k]>0){sum+=comps[k]*w[k];ws+=w[k]}});
  const total=ws?sum/ws:0;
  // harde filters
  if(isCarrier(s.wffs)&&isCarrier(m.wffs)){excluded=true;warnings.push({lvl:"bad",t:"Beide ouders zijn WFFS-drager: risico op een niet-levensvatbaar veulen (25% of meer)."})}
  else if(isCarrier(s.wffs)&&(!m.wffs||m.wffs==="onbekend")){warnings.push({lvl:"warn",t:"Hengst is WFFS-drager en de WFFS-status van de merrie is onbekend. Laat de merrie testen."})}
  else if(isCarrier(m.wffs)&&(!s.wffs||s.wffs==="onbekend")){warnings.push({lvl:"warn",t:"Merrie is WFFS-drager en de WFFS-status van de hengst is onbekend."})}
  const Fp=c.F*100;
  if(Fp>=t.max){excluded=true;warnings.push({lvl:"bad",t:`Inteelt ${pct(c.F)} ligt op of boven de uitsluitingsgrens (${fn(t.max)}%).`})}
  else if(Fp>=t.warn){warnings.push({lvl:"warn",t:`Inteelt ${pct(c.F)} ligt op of boven de waarschuwingsgrens (${fn(t.warn)}%).`})}
  if(s.ocd==="bevinding"||m.ocd==="bevinding")warnings.push({lvl:"warn",t:"OC/OCD-bevinding bij "+(s.ocd==="bevinding"?s.naam:m.naam)+"."});
  // uitleg
  if(z!=null){if(z>=.75)reasons.push(`sterke fokwaarden (gemiddeld ${fz(z)} SD)`);else if(z<0)weak.push(`fokwaarden onder het gemiddelde (${fz(z)} SD)`)}else weak.push("geen fokwaarden bekend");
  const best=[s,m].filter(h=>num(h.hoogste_niveau_cm)!=null).sort((a,b)=>b.hoogste_niveau_cm-a.hoogste_niveau_cm)[0];
  if(best&&best.hoogste_niveau_cm>=150)reasons.push(`${best.naam} sprong zelf ${fmtH(best.hoogste_niveau_cm)}`);
  [s,m].forEach(h=>{const o=h.nakomelingen||{};const sp=num(o.sport);if(sp&&sp>=5){const p=(num(o.m140)||0)/sp;if(p>=.2)reasons.push(`${Math.round(p*100)}% van de sportnakomelingen van ${h.naam} op 1m40 of hoger`)}});
  if(c.F<.02)reasons.push(`lage inteelt (${pct(c.F)})`);
  if(s.wffs==="N/N"&&m.wffs==="N/N")reasons.push("beide WFFS-vrij (N/N)");
  if(data<50)weak.push("weinig bevestigde data");
  const conf=data>=75?"hoog":data>=45?"middel":"laag";
  return{s,m,total,comps,coi:c,excluded,warnings,reasons,weak,conf,z}}

