const V_COLL="veilingen",C_COLL="council";
const VM_TRIGGER="veilingmeester";
const SUFFIX=new Set(["z","vdl","stx","ask","hn","frh","ps","tn","old","pjl","jw","ls"]);
const keyL=(s)=>{let t=String(s||"").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/[^a-z0-9 ]+/g," ").trim().split(/\s+/).filter(w=>w&&!SUFFIX.has(w));
  if(t.length>1&&/^\d+$/.test(t[t.length-1]))t=t.slice(0,-1);return t.join("")};
const euro=(x)=>x==null?"onbekend":"€ "+Math.round(x).toLocaleString("nl-BE");
const ORG=[[/nijhof/i,"Team Nijhof"],[/zangersheide|365-auctions/i,"Zangersheide"],[/bwp/i,"BWP"],[/flanders (foal|embryo|horse)/i,"Flanders Foal & Embryo Auction"],[/horse auction belgium/i,"Horse Auction Belgium"],[/holsteiner|tomorrow.s champions/i,"Holsteiner Verband"],[/verden/i,"Hannoveraner (Verden)"],[/westf/i,"Westfalen"],[/oldenburg/i,"Oldenburg"],[/fences/i,"Fences"],[/goresbridge/i,"Goresbridge"],[/cavan/i,"Cavan"],[/paardenveilingonline/i,"Paardenveilingonline"],[/kwpn/i,"KWPN"],[/youhorse/i,"YouHorse"],[/dutch horse trading/i,"Dutch Horse Trading"],[/limburgse/i,"Limburgse Veulenveiling"],[/tops international/i,"Tops"],[/prinsjesdag/i,"Prinsjesdag"],[/psi|schockem/i,"PSI"],[/ierse|irish/i,"Ierland overig"]];
const huisOf=(n)=>{for(const [r,l] of ORG)if(r.test(n||""))return l;return String(n||"Onbekend").split(/[\s:-]+/).slice(0,2).join(" ")};
const CAT_LAB={veulen:"Veulen",jong:"Jong paard",sport:"Sportpaard",fokmerrie:"Fokmerrie",embryo:"Embryo",overig:"Overig"};
const ST_LAB={verkocht:"Verkocht",niet_verkocht:"Niet verkocht",aangekondigd:"Aangekondigd",onbekend:"Status onzeker"};
function median(a){if(!a.length)return null;const s=a.slice().sort((x,y)=>x-y);const i=Math.floor(s.length/2);return s.length%2?s[i]:(s[i-1]+s[i])/2}
function buildLots(){const out=[];(state.veilingen||[]).forEach(v=>{(v.lots||[]).forEach((l,i)=>{out.push(Object.assign({},l,{_veiling:v.veiling,_huis:huisOf(v.veiling),_datum:v.datum||"",_regio:v.regio||"",_vid:v.id,_i:i,_kv:keyL(l.vader),_km:keyL(l.moeder),_kmv:keyL(l.moedersvader),_prijs:l.status==="verkocht"?num(l.prijs_eur):null}))})});
  out.sort((a,b)=>String(b._datum).localeCompare(String(a._datum)));state.lots=out}
function stats(lots){const p=lots.map(l=>l._prijs).filter(x=>x!=null&&x>0);
  return{n:lots.length,sold:lots.filter(l=>l.status==="verkocht").length,np:p.length,med:median(p),avg:p.length?p.reduce((a,b)=>a+b,0)/p.length:null,max:p.length?Math.max(...p):null,min:p.length?Math.min(...p):null}}
function yearTrend(lots){const by={};lots.forEach(l=>{if(l._prijs==null)return;const y=String(l._datum).slice(0,4);if(!/^\d{4}$/.test(y))return;(by[y]=by[y]||[]).push(l._prijs)});
  return Object.keys(by).sort().map(y=>({jaar:y,n:by[y].length,mediaan:median(by[y])}))}
function trendOf(lots){const f=lots.filter(l=>l.categorie==="veulen");const tf=yearTrend(f);const w=trendWord(tf);return w!=="onbekend"?w:trendWord(yearTrend(lots))}
function trendWord(tr){if(tr.length<2)return"onbekend";const a=tr[tr.length-2],b=tr[tr.length-1];if(a.n<3||b.n<3)return"onbekend";const r=b.mediaan/a.mediaan;return r>1.1?"stijgend":r<0.9?"dalend":"stabiel"}
const hKeys=(h)=>new Set([h.naam,...(h.naam_varianten||[])].map(keyL).filter(Boolean));
function lotsFor(h){const K=hKeys(h);if(!K.size||!state.lots)return{alsVader:[],alsMoeder:[],alsMV:[],zelf:[]};
  return{alsVader:state.lots.filter(l=>K.has(l._kv)),alsMoeder:h.geslacht==="merrie"?state.lots.filter(l=>K.has(l._km)):[],alsMV:state.lots.filter(l=>K.has(l._kmv)),zelf:state.lots.filter(l=>K.has(keyL(l.naam)))}}
function marketHtml(h){if(!state.lots||!state.lots.length)return"";const f=lotsFor(h);const rows=[["Nakomelingen geveild",f.alsVader.length?f.alsVader:f.alsMoeder],["Als moedersvader",f.alsMV],["Zelf geveild",f.zelf]].filter(r=>r[1].length);
  if(!rows.length)return"";
  return `<h3 style="margin-top:16px">Veilingen</h3><dl class="facts">${rows.map(([lab,ls])=>{const s=stats(ls);return `<dt>${lab}</dt><dd><span class="num">${s.n}</span> lots, <span class="num">${s.np}</span> met prijs${s.med!=null?`, mediaan <span class="num">${euro(s.med)}</span>, hoogste <span class="num">${euro(s.max)}</span>`:""}</dd>`}).join("")}</dl>
   <button class="btn ghost" type="button" data-act="veil" data-id="${esc(h.id)}" style="margin-top:6px">Toon in Veilingen</button>`}
function marketFor(s,m){const KS=hKeys(s),KM=hKeys(m),ks=keyL(s.naam),kmv=keyL(m.stamboom&&m.stamboom.v),km=keyL(m.naam),kmm=keyL(m.stamboom&&m.stamboom.m);const L=state.lots||[];
  const pick=(ls,n)=>ls.filter(l=>l._prijs!=null).slice(0,n).map(l=>({naam:l.naam,cat:l.categorie,vader:l.vader,moedersvader:l.moedersvader,prijs_eur:l._prijs,veiling:l._veiling,datum:l._datum}));
  const sire=L.filter(l=>KS.has(l._kv)),sireFoal=sire.filter(l=>l.categorie==="veulen"),dsire=kmv?L.filter(l=>l._kmv===kmv):[],combo=kmv?sire.filter(l=>l._kmv===kmv):[],mare=L.filter(l=>KM.has(l._km)),dam=kmm?L.filter(l=>l._km===kmm):[];
  const sum=(ls)=>{const st=stats(ls);return{lots:st.n,met_prijs:st.np,mediaan:st.med,gemiddelde:st.avg&&Math.round(st.avg),min:st.min,max:st.max}};
  const all=L.filter(l=>l.categorie==="veulen");
  return{totaal_lots_in_database:L.length,veulens_algemeen:sum(all),
   hengst:{naam:s.naam,alle:sum(sire),veulens:sum(sireFoal),trend_per_jaar:yearTrend(sire),trend:trendOf(sire),trend_basis:"veulens per jaar als er genoeg zijn, anders alle lots",voorbeelden:pick(sire,8)},
   moedersvader_van_veulen:{naam:m.stamboom&&m.stamboom.v||null,alle:sum(dsire),veulens:sum(dsire.filter(l=>l.categorie==="veulen")),voorbeelden:pick(dsire,5)},
   zelfde_combinatie_vader_x_moedersvader:{alle:sum(combo),voorbeelden:pick(combo,5)},
   merrie_als_moeder:{alle:sum(mare),voorbeelden:pick(mare,5)},
   grootmoeder_als_moeder:{naam:m.stamboom&&m.stamboom.m||null,alle:sum(dam),voorbeelden:pick(dam,4)}}}
