  const sorted=state.horses.slice().sort((a,b)=>String(a.naam).localeCompare(String(b.naam)));
  const roots=new Map();g.nodes.forEach(n=>{if(!g.mother.has(n.k)&&g.kids.has(n.k)){roots.set(n.k,lineCount(g,n.k))}});
  const top=[...roots.entries()].sort((a,b)=>b[1]-a[1]).slice(0,12).filter(e=>e[1]>=2);
  if(!state.stamSel||!byId(state.stamSel)){const big=top.length?sorted.filter(x=>x.geslacht==="merrie"&&rootOf(g,norm(x.naam))===top[0][0]):[];
    const firstM=big[0]||sorted.find(x=>x.geslacht==="merrie")||sorted[0];state.stamSel=firstM.id}
  $("stPaard").innerHTML=sorted.map(h=>`<option value="${esc(h.id)}"${h.id===state.stamSel?" selected":""}>${esc(h.naam)}${h.geboortejaar?" ("+esc(h.geboortejaar)+")":""}</option>`).join("");
  // grootste stamlijnen
  $("stTop").innerHTML=top.length?`<div class="label" style="margin-bottom:6px">Grootste stamlijnen in de database</div><div style="display:flex;flex-wrap:wrap;gap:6px">${top.map(([k,c])=>{const n=g.nodes.get(k);return`<button type="button" class="btn ghost" style="padding:4px 10px;font-size:13px" data-stroot="${esc(k)}">${esc(n.name)}${n.stam?" · stam "+esc(n.stam):""} <span class="muted">(${c})</span></button>`}).join("")}</div>`:"";
  const h=byId(state.stamSel);const selK=norm(h.naam);const rootK=state.stamRoot&&g.nodes.has(state.stamRoot)?state.stamRoot:rootOf(g,selK);
  const depth=Number($("stDiepte").value)||6;const sons=$("stZonen").value!=="nee";
  // pad van stammoeder naar gekozen paard
  const path=new Set();{let cur=selK,seen=new Set();while(cur&&!seen.has(cur)){seen.add(cur);path.add(cur);if(cur===rootK)break;cur=g.mother.get(cur)}if(!path.has(rootK))path.clear()}
  // boom opbouwen
