const REQ_COLL="aanvragen";
const STATUS={wachtrij:["In wachtrij",""],bezig:["Wordt opgezocht","warn"],klaar:["Klaar voor review","good"],niet_gevonden:["Niet gevonden","bad"],goedgekeurd:["Toegevoegd","good"],afgekeurd:["Afgekeurd",""]};
