  const by=(a,b)=>String(b.aangevraagd_op||"").localeCompare(String(a.aangevraagd_op||""));
  const all=[...state.aanvragen].sort(by);
  const groups=[["Klaar voor review",all.filter(a=>a.status==="klaar"||a.status==="niet_gevonden")],["In de wachtrij",all.filter(a=>a.status==="wachtrij"||a.status==="bezig")],["Afgehandeld",all.filter(a=>a.status==="goedgekeurd"||a.status==="afgekeurd")]];
  const row=(a)=>`<button class="item" type="button" data-req="${esc(a.id)}" aria-current="${a.id===state.revSel}"><span class="sex">${a.voorstel&&a.voorstel.geslacht==="hengst"?"H":a.voorstel&&a.voorstel.geslacht==="merrie"?"M":"?"}</span><span style="min-width:0"><span class="name">${esc(a.voorstel&&a.voorstel.naam||a.naam)}</span><br><span class="small muted">aangevraagd ${esc(fmtDate(a.aangevraagd_op))}</span></span>${pill(a.status)}</button>`;
