const kName=(k)=>typeof k==="string"?k:(k&&k.naam)||"?";
const kInfo=(k)=>{if(!k||typeof k==="string")return"";const p=[];if(k.jaar)p.push(k.jaar);if(k.vader||k.moedersvader)p.push((k.vader||"?")+" x "+(k.moedersvader||"?"));if(k.stamboek)p.push(k.stamboek);if(k.bron)p.push("via "+k.bron);return p.join(" · ")};
function lev(a,b){if(a===b)return 0;const m=a.length,n=b.length;if(!m)return n;if(!n)return m;let prev=Array.from({length:n+1},(_,j)=>j);for(let i=1;i<=m;i++){const cur=[i];for(let j=1;j<=n;j++)cur[j]=Math.min(prev[j]+1,cur[j-1]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=cur}return prev[n]}
const STRIP=/^(vdl|gk|hh|h&m|gl events|stx|sfn|ask)\s+|\s+(z|vdl|stx|hn|ask|frh|ps|tn|sitte|old|sf|kwpn|bwp)$/g;
const fuzzKey=(s)=>norm(String(s||"").toLowerCase().replace(STRIP,"").replace(STRIP,"").replace(/\bv\.?\s?d\.?\b|\bvan de\b|\bvan den\b|\bvan het\b|\bvh\b/g,"vd"));
function closeMatches(q,list){const k=fuzzKey(q);if(k.length<3)return[];return list.map(h=>{const hk=fuzzKey(h.naam);const d=lev(k,hk);const tol=k.length<=6?1:2;return{h,d:hk.includes(k)||k.includes(hk)?Math.min(d,1):d,tol}}).filter(x=>x.d<=x.tol).sort((a,b)=>a.d-b.d).slice(0,5).map(x=>x.h)}
