function missingOf(v){const m=[];if(!v.ueln)m.push("UELN");if(!v.fei_id)m.push("FEI-ID");if(!v.geboortejaar)m.push("geboortejaar");if(!v.stamboek)m.push("stamboek");if(num(v.stokmaat_cm)==null)m.push("stokmaat");if(num(v.hoogste_niveau_cm)==null)m.push("hoogste niveau");if(!v.wffs||v.wffs==="onbekend")m.push("WFFS-status");if(!v.ocd||v.ocd==="onbekend")m.push("OCD-status");const n=ancCount(v);if(n<14)m.push(`stamboom (${n} van 14 voorouders)`);return m}
