function applyFixes(v,now){const fixed=[];const val=(id)=>{const el=$(id);return el?el.value.trim():null};
  const userSrc=()=>{v.bronnen=v.bronnen||[];let i=v.bronnen.findIndex(b=>b&&b.gebruiker);if(i<0){v.bronnen.push({naam:"Aangevuld door gebruiker"+(val("fxBron")?": "+val("fxBron"):""),datum:now.slice(0,10),gebruiker:true});i=v.bronnen.length-1}return i};
  const n=val("fxNaam");if(n){v.naam=n;fixed.push("naam")}
  const s=val("fxSex");if(s){v.geslacht=s;fixed.push("geslacht")}
  const u=val("fxUeln");if(u!==null){const c=u.toUpperCase().replace(/\s/g,"");if(c&&c.length===15)v.ueln=c;else delete v.ueln;fixed.push("ueln")}
  const b=val("fxBron");if(b&&!(v.bronnen||[]).some(x=>x&&x.naam&&!x.gebruiker))fixed.push("bron");
  if(badFok(v)){const drop=v.fokwaarden.filter(f=>!f.systeem||f.waarde==null||f.gemiddelde==null||!f.sd);v.fokwaarden=v.fokwaarden.filter(f=>!drop.includes(f));v.opmerking=((v.opmerking||"")+" Weggelaten fokwaarden zonder schaal: "+drop.map(f=>`${f.systeem||"?"} ${f.waarde??"?"}`).join(", ")+".").trim();fixed.push("fokwaarden")}
  if(fixed.some(k=>k!=="fokwaarden")||b){const i=userSrc();v.herkomst=v.herkomst||{};fixed.filter(k=>k!=="fokwaarden"&&k!=="bron").forEach(k=>{v.herkomst[k]=i})}
  return fixed}
