  const [emb,hor]=await Promise.all([fwImg(FW_EMBLEM),fwImg(FW_HORSES)]);
  const s=h.stamboom||{};
  // Zelfde ontwerp op elke grootte: afstanden schalen mee met de breedte, letters zo groot als past.
  const k=W/1123,sp=(x)=>x*k;
  const pad=Math.max(12,sp(44));
  const niv=num(h.hoogste_niveau_cm)!=null?"niveau "+Math.floor(h.hoogste_niveau_cm/100)+"m"+String(h.hoogste_niveau_cm%100).padStart(2,"0"):"";
  const facts=[h.geslacht,h.geboortejaar,h.stamboek,h.ueln?"UELN "+h.ueln:"",num(h.stokmaat_cm)!=null?h.stokmaat_cm+" cm":"",niv].filter(Boolean).join("  ·  ");
  // Liggende plek in de app (breder dan A4): kop en voet compacter, verder hetzelfde ontwerp.
  const cmp=H<W*.62;const er=emb.height/emb.width;
  const ew=cmp?Math.min(Math.max(46,sp(120)),Math.max(40,H*.19)/er):Math.max(46,sp(120)),eh=ew*er,headTop=cmp?8:Math.max(10,sp(30));
