  const tf=cmp?Math.min(1,Math.max(.55,eh/104*1.15)):Math.min(1,Math.max(.55,k*1.3));
  const tx=pad+ew+Math.max(10,sp(24)),tMax=W-pad-tx;
  const kSz=Math.max(opt.minPx?10:0,13*tf);
  let tsz=38*tf;c.font=`700 ${tsz}px ${DISP}`;while(c.measureText(h.naam||"").width>tMax&&tsz>14){tsz-=1;c.font=`700 ${tsz}px ${DISP}`}
  let fsz=Math.max(opt.minPx?11:0,15*tf);c.font=`400 ${fsz}px ${BODY}`;while(c.measureText(facts).width>tMax&&fsz>(opt.minPx?11:9)){fsz-=.5;c.font=`400 ${fsz}px ${BODY}`}
  const gapK=Math.max(7,kSz*.85),gapT=Math.max(6,tsz*.3);
  const hBlock=kSz*.75+gapK+tsz*.72+gapT+fsz*.8;
  const by0=headTop+Math.max(0,(eh-hBlock)/2);
  const kickY=by0+kSz*.75,titleY=kickY+gapK+tsz*.72,factY=titleY+gapT+fsz*.8;
  const lineY=Math.max(headTop+eh,by0+hBlock+fsz*.25)+(cmp?6:Math.max(6,sp(14)));
  const top=lineY+(cmp?8:Math.max(10,sp(20))),bottom=H-(cmp?24:Math.max(30,sp(74))),left=pad,right=W-pad,gap=Math.max(3,sp(6));
  const fixed=Math.max(16,sp(26)),fr=[.9,1.15,1,1],unit=(right-left-fixed-gap*4)/(fr[0]+fr[1]+fr[2]+fr[3]);
  const ws=[fixed,fr[0]*unit,fr[1]*unit,fr[2]*unit,fr[3]*unit],xs=[left];for(let i=1;i<5;i++)xs[i]=xs[i-1]+ws[i-1]+gap;
  cv._lay={W,subjX:xs[1],parEnd:xs[2]+ws[2]};
