  const cells=[["v",2,1,4],["m",2,5,4]].concat(PC_G2.map((x,i)=>[x,3,1+i*2,2]),PC_G3.map((x,i)=>[x,4,1+i,1]));
  const dotX=Math.max(8,sp(14)),txtX=Math.max(15,sp(26)),rad=Math.max(3,sp(4.5));
  const cellFont=(key,f)=>key.length===1?`700 ${17*f}px ${DISP}`:`${key.length===2?600:400} ${(key.length===3?14:15.5)*f}px ${BODY}`;
  // grootste lettergrootte zoeken waarbij elke naam volledig past (max. 3 regels)
