  const fits=(f)=>{for(const [key,col,row,span] of cells){const v=s[key]||"onbekend";c.font=cellFont(key,f);const lh=(key.length===1?21:18)*f;const lines=pcWrap(c,v,ws[col]-txtX-6,9);if(lines.length>3||lines.length*lh>rh(span)-2)return false;if(lines.some(l=>c.measureText(l).width>ws[col]-txtX-4))return false}
    c.font=`700 ${22*f}px ${DISP}`;const nl=pcWrap(c,h.naam||"",ws[1]-Math.max(16,sp(32)),9);return nl.length<=4&&nl.every(l=>c.measureText(l).width<=ws[1]-Math.max(12,sp(28)))};
  const fMin=opt.minPx?opt.minPx/14:.58;
  while(f>fMin&&!fits(f))f-=.03;
  f=Math.max(f,fMin);
  // achtergrond
  const bg=c.createLinearGradient(0,0,0,lineY+10);bg.addColorStop(0,CREAM);bg.addColorStop(1,"#FFFFFF");c.fillStyle=bg;c.fillRect(0,0,W,H);
