  const rr=(x,y,w,hh,r)=>{c.beginPath();c.moveTo(x+r,y);c.arcTo(x+w,y,x+w,y+hh,r);c.arcTo(x+w,y+hh,x,y+hh,r);c.arcTo(x,y+hh,x,y,r);c.arcTo(x,y,x+w,y,r);c.closePath()};
  // zijlabels
  [["VADERZIJDE",1],["MOEDERZIJDE",5]].forEach(([t,r])=>{const y=ry(r),hh=rh(4);c.strokeStyle=GOLD;c.lineWidth=1.5;c.beginPath();c.moveTo(xs[0]+ws[0],y);c.lineTo(xs[0]+ws[0],y+hh);c.stroke();
    c.save();c.translate(xs[0]+ws[0]/2+Math.max(2,sp(4)),y+hh/2);c.rotate(-Math.PI/2);c.fillStyle=GOLD;let ls=11*tf;c.font=`700 ${ls}px ${DISP}`;c.letterSpacing=(3*tf)+"px";
    while(c.measureText(t).width+t.length*3*tf>hh-6&&ls>(opt.minPx?8.5:6)){ls-=.5;c.font=`700 ${ls}px ${DISP}`}c.textAlign="center";c.fillText(t,0,0);c.restore();c.letterSpacing="0px"});
  // het paard zelf
  rr(xs[1],top,ws[1],rh(8),Math.max(5,sp(10)));c.fillStyle=GREEN;c.fill();
  // naam van het paard: liefst op één regel, anders zo weinig mogelijk regels
  const inX=Math.max(8,sp(16));let nsz=22*f,nl;const nw=ws[1]-inX*2;
  for(;;){c.font=`700 ${nsz}px ${DISP}`;nl=pcWrap(c,h.naam||"",nw,4);if((nl.length===1||nsz<=15*f)&&nl.every(l=>c.measureText(l).width<=nw))break;if(nsz<=11){break}nsz-=1}
  c.fillStyle="#F3EEE3";const nlh=nsz*1.28;
  const sub=[h.geslacht,h.geboortejaar].filter(Boolean).join(" · ");const blockH=nl.length*nlh+(sub?18*f:0);let by=top+rh(8)/2-blockH/2+nlh*.8;
  nl.forEach((l,i)=>c.fillText(l,xs[1]+inX,by+i*nlh));
