  // voorouders
  for(const [key,col,row,span] of cells){const x=xs[col],y=ry(row),w=ws[col],hh=rh(span);const v=s[key];
    c.fillStyle=key.length===1?CREAM:"rgba(255,255,255,.82)";c.fillRect(x,y,w,hh);
    c.strokeStyle=LINE;c.lineWidth=1;c.beginPath();c.moveTo(x,y+hh-.5);c.lineTo(x+w,y+hh-.5);c.stroke();
    c.fillStyle=pcMale(key)?GREEN:GOLD;c.beginPath();c.arc(x+dotX,y+hh/2,rad,0,Math.PI*2);c.fill();
    c.font=v?cellFont(key,f):`italic 400 ${14*f}px ${BODY}`;c.fillStyle=v?(key.length===1?GREEN:INK):MUTED;
    const lines=pcWrap(c,v||"onbekend",w-txtX-6,3);const lh=(key.length===1?21:18)*f;const y0=y+hh/2-(lines.length-1)*lh/2+lh*.3;
    lines.forEach((l,i)=>c.fillText(l,x+txtX,y0+i*lh))}
  // legende en voet
  const legY=cmp?H-9:H-Math.max(16,sp(48)),footY=cmp?H-9:H-Math.max(6,sp(22));const lf=Math.max(opt.minPx?11:8.5,12*tf);
  c.font=`400 ${lf}px ${BODY}`;c.textAlign="left";
  c.fillStyle=GREEN;c.beginPath();c.arc(left+rad,legY-lf*.35,rad,0,Math.PI*2);c.fill();c.fillStyle=MUTED;c.fillText("hengst",left+rad*2+4,legY);
  const mx=left+rad*2+4+c.measureText("hengst").width+14;c.fillStyle=GOLD;c.beginPath();c.arc(mx+rad,legY-lf*.35,rad,0,Math.PI*2);c.fill();c.fillStyle=MUTED;c.fillText("merrie",mx+rad*2+4,legY);
  const legEnd=mx+rad*2+4+c.measureText("merrie").width;
  if(!opt.compact&&!cmp){c.textAlign="right";c.fillText("Gemaakt op "+new Date().toLocaleDateString("nl-BE")+". Controleer gegevens altijd bij het stamboek.",right,legY)}
  c.fillStyle=GREEN;const ffs=Math.max(opt.minPx?9.5:7,11*tf);c.font=`600 ${ffs}px ${DISP}`;const lsp=3*tf;c.letterSpacing=lsp+"px";const ft="DE FOKWIJZER  ·  EEN WIKIGIDS VOOR EN DOOR PAARDENFOKKERS";const fw=c.measureText(ft).width;
  c.strokeStyle=GOLD;c.lineWidth=1;c.beginPath();
  if(cmp){c.textAlign="right";c.fillText(ft,right,footY);c.moveTo(legEnd+12,footY-ffs*.35);c.lineTo(right-fw-12,footY-ffs*.35)}
  else{c.textAlign="center";c.fillText(ft,W/2,footY);c.moveTo(left,footY-ffs*.35);c.lineTo(W/2-fw/2-12,footY-ffs*.35);c.moveTo(W/2+fw/2+12,footY-ffs*.35);c.lineTo(right,footY-ffs*.35)}
