const RUN_TRIGGER="verwerking";const RUN_SERVER="Claude Code Remote";const RUN_COOLDOWN=10*60*1000;
let mcpNs=null,mcpChecked=false;state.run=null;let runMsg="";
function renderRun(){const btn=$("runBtn"),info=$("runInfo");const wacht=state.aanvragen.filter(a=>a.status==="wachtrij").length;const bezig=state.aanvragen.filter(a=>a.status==="bezig").length;
  const last=state.run&&state.run.gestart_op?Date.parse(state.run.gestart_op):0;const recent=last&&(Date.now()-last<RUN_COOLDOWN);
  btn.textContent=wacht?`Start verwerking (${wacht})`:"Start verwerking";
  btn.disabled=!wacht||!mcpNs||!state.canWrite||(recent&&!!bezig)||runBusy;
  let t="";
  if(runMsg)t=runMsg;
  else if(mcpChecked&&!mcpNs)t="Automatisch verwerken is niet ingesteld op deze server, of je bent niet ingelogd als paarden-beheerder.";
  else if(bezig)t=`De agent werkt aan ${bezig} aanvraag${bezig>1?"en":""}. Resultaten verschijnen hier vanzelf.`;
  else if(!wacht)t="Niets in de wachtrij.";
  else if(last)t="Laatst gestart: "+fmtDate(state.run.gestart_op)+".";
  info.textContent=t}
let runBusy=false;
$("runBtn").addEventListener("click",async()=>{if(!mcpNs||runBusy)return;runBusy=true;runMsg="Verwerking wordt gestart...";renderRun();
  try{await mcpNs.callTool(RUN_SERVER,"fire_trigger",{trigger_id:RUN_TRIGGER},{cache:false});
    const now=new Date().toISOString();runMsg="Verwerking gestart om "+fmtDate(now)+". De aanvragen gaan zo naar 'Wordt opgezocht' en daarna naar 'Klaar voor review'.";
    try{await db.doc("systeem/verwerking").set({gestart_op:now})}catch(_){}}
  catch(err){const c=err&&err.code;
    runMsg=c==="needs_reauth"?"Log opnieuw in.":
      c==="server_not_connected"||c==="selection_required"?"Automatisch verwerken is niet ingesteld op deze server.":
      c==="not_in_manifest"||c==="approval_required"||c==="consent_required"?"Je hebt de pagina (nog) geen toestemming gegeven om de verwerking te starten. Klik opnieuw en kies Toestaan.":
      c==="tool_error"?"De verwerking kon niet gestart worden: "+(err.message||"onbekende fout"):
      c==="server_unavailable"||c==="upstream_error"?"Geen antwoord ontvangen. Kijk over een minuut of de aanvragen op 'Wordt opgezocht' staan voor je opnieuw klikt.":
      (err&&err.message)||"Starten lukte niet.";}
  finally{runBusy=false;renderRun()}});

